              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

function SoilCard({ label, value, icon, good }: { label: string; value: string; icon: string; good: boolean }) {
  const { tx } = useLang()
  return (
    <div className="bg-white rounded-lg border border-gray-100 p-3 text-center">
      <span className="text-xl">{icon}</span>
